"""Implement a Max Heap — the min heap with the comparison flipped.

Time: O(log n) push/pop, O(1) peek   Space: O(n)
"""


class MaxHeap:
    def __init__(self):
        self._data = []

    def _sift_up(self, i: int) -> None:
        while i > 0:
            parent = (i - 1) // 2
            if self._data[i] <= self._data[parent]:
                break
            self._data[i], self._data[parent] = self._data[parent], self._data[i]
            i = parent

    def _sift_down(self, i: int) -> None:
        n = len(self._data)
        while True:
            largest = i
            for child in (2 * i + 1, 2 * i + 2):
                if child < n and self._data[child] > self._data[largest]:
                    largest = child
            if largest == i:
                return
            self._data[i], self._data[largest] = self._data[largest], self._data[i]
            i = largest

    def push(self, val: int) -> None:
        self._data.append(val)
        self._sift_up(len(self._data) - 1)

    def pop(self) -> int:
        if not self._data:
            return -1
        top = self._data[0]
        last = self._data.pop()
        if self._data:
            self._data[0] = last
            self._sift_down(0)
        return top

    def peek(self) -> int:
        return self._data[0] if self._data else -1

    def size(self) -> int:
        return len(self._data)
